-- ================================================================================================
-- Sierra de Salinas · N2 completo: espacio, hábitats, especies y vínculos.
--
-- GENERADO por Tools/catalogo-nacional/build-park-sql.js desde Frontend\Data\parks\murcia\sierra-de-salinas\park.json
-- y Data/parks/murcia/sierra-de-salinas/geo/habitats.geojson. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-park-sql.js --park sierra-de-salinas
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado:
-- con backend desplegado, un espacio que no esté en la base de datos no existe para el usuario.
--
-- Contenido: 1 espacio · 7 hábitats · 209 especies · 179 vínculos especie↔hábitat.
-- Los puntos de interés van aparte, en `n3-pois-<slug>.sql` (build-poi-sql.js).
--
-- ORDEN: la fila de `parks` va PRIMERO y no es opcional. Sin ella los INSERT ... SELECT de
-- abajo no encuentran nada y cargan CERO filas sin dar ningún error.
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre las claves únicas del esquema. Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database\sierra-de-salinas-n2.sql
-- ================================================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------------------------------------
-- 1. El espacio. Sin esta fila, TODO lo demás carga cero filas en silencio.
-- ------------------------------------------------------------------------------------------------
INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('sierra-de-salinas', 'Sierra de Salinas', 'Paisaje Protegido', 'Región de Murcia', 'Murcia', 'Yecla', 'Sierra compartida con Alicante sobre el altiplano de Yecla: pinar, carrascal y umbrías frescas, una de las masas forestales mejor conservadas.', 38.49335, -1.04485, 'available')
ON DUPLICATE KEY UPDATE
    name = VALUES(name), category = VALUES(category), region = VALUES(region),
    province = VALUES(province), municipality = VALUES(municipality),
    description = VALUES(description), latitude = VALUES(latitude),
    longitude = VALUES(longitude), status = VALUES(status);

-- ------------------------------------------------------------------------------------------------
-- 2. Hábitats (7). `geometry` sale del geojson; sin ella el mapa dibuja un círculo.
-- ------------------------------------------------------------------------------------------------
