    SELECT 'encinares-de-quercus-9340', '9340', 'Encinares de Quercus ilex y Quercus rotundifolia', 'Bosque', 'El bosque mediterráneo por excelencia: encinares y carrascales de hoja dura, pequeña y perenne, que aguantan tanto el calor del verano como las heladas del interior. Bajo los árboles crece un sotobosque denso de coscoja, lentisco, madroño, enebros y aromáticas, y en el suelo la bellota sostiene en otoño a jabalíes, palomas y arrendajos. Aclarado por el ser humano durante siglos, ha dado lugar a las dehesas.', 0, 38.501435, -1.032991, '#6b8e23', '{"type":"Polygon","coordinates":[[[-1.057046,38.495197],[-1.056958,38.49506],[-1.0569,38.494969],[-1.056812,38.494887],[-1.056724,38.494772],[-1.056637,38.494672],[-1.056578,38.494581],[-1.056534,38.494485],[-1.056534,38.494359],[-1.056504,38.494269],[-1.05646,38.494169],[-1.056431,38.494051],[-1.056402,38.493925],[-1.056358,38.493825],[-1.056314,38.49372],[-1.056299,38.49363],[-1.056226,38.493516],[-1.056167,38.493412],[-1.05608,38.493311],[-1.055904,38.493286],[-1.055788,38.493288],[-1.055642,38.493254],[-1.055511,38.493252],[-1.055394,38.493255],[-1.055248,38.493198],[-1.055131,38.493151],[-1.055,38.493081],[-1.054868,38.493039],[-1.054709,38.493036],[-1.054577,38.493061],[-1.05446,38.493086],[-1.0543,38.493128],[-1.054183,38.493189],[-1.054082,38.493291],[-1.053965,38.493348],[-1.053877,38.493428],[-1.053761,38.493475],[-1.053645,38.493509],[-1.05347,38.493533],[-1.053309,38.493535],[-1.053192,38.493511],[-1.053017,38.49349],[-1.052843,38.493487],[-1.052711,38.493453],[-1.052565,38.493433],[-1.052434,38.493399],[-1.052303,38.493365],[-1.052171,38.493332],[-1.05204,38.493298],[-1.051894,38.493237],[-1.051777,38.493203],[-1.05166,38.49317],[-1.0515,38.493104],[-1.051383,38.493066],[-1.051252,38.493032],[-1.051106,38.493012],[-1.050975,38.492987],[-1.050829,38.492953],[-1.050726,38.492911],[-1.05058,38.492877],[-1.050435,38.49283],[-1.050303,38.492773],[-1.050084,38.492671],[-1.049953,38.492646],[-1.049836,38.49261