    SELECT 'matorrales-mediterraneos-y-4090', '4090', 'Matorrales mediterráneos y oromediterráneos primarios y secundarios con dominio frecuente de genisteas', 'Matorral', 'Matorral almohadillado de montaña: matas espinosas y compactas —piornos, erizones, aulagas y aliagas— que crecen pegadas al suelo formando cojines redondeados. Esa forma no es casual, es la respuesta al viento, al frío y al peso de la nieve, y por dentro guarda un microclima donde se refugian otras plantas. Aparece por encima o en el lugar del bosque, en crestas y laderas expuestas.', 0, 38.495734, -1.019903, '#4f7942', '{"type":"Polygon","coordinates":[[[-1.026492,38.494154],[-1.0264,38.493774],[-1.026016,38.493385],[-1.025547,38.493169],[-1.024903,38.493037],[-1.024435,38.492916],[-1.02375,38.493008],[-1.023225,38.493049],[-1.022904,38.493071],[-1.022481,38.493077],[-1.021778,38.49284],[-1.021165,38.492771],[-1.02062,38.492897],[-1.020366,38.492852],[-1.020319,38.492874],[-1.020173,38.492907],[-1.020043,38.492928],[-1.019882,38.492988],[-1.019751,38.493008],[-1.019619,38.493056],[-1.019473,38.493089],[-1.019357,38.493123],[-1.019182,38.493192],[-1.019051,38.493217],[-1.01889,38.493287],[-1.01873,38.49332],[-1.018629,38.493377],[-1.018468,38.493446],[-1.018351,38.493507],[-1.018234,38.493586],[-1.018074,38.493678],[-1.017929,38.493757],[-1.017826,38.493805],[-1.017637,38.493905],[-1.017506,38.493989],[-1.01736,38.494081],[-1.017201,38.494182],[-1.017025,38.494296],[-1.016924,38.49438],[-1.016807,38.494468],[-1.01669,38.494551],[-1.016588,38.494617],[-1.016486,38.494701],[-1.016297,38.494838],[-1.016237,38.494874],[-1.014918,38.49631],[-1.013923,38.49705],[-1.01434,38.497699],[-1.014533,38.497966],[-1.014976,38.498582],[-1.01547,38.499266],[-1.01563,38.499488],[-1.015725,38.499455],[-1.015956,38.499225],[-1.016127,38.498881],[-1.016445,38.498593],[-1.016968,38.498381],[-1.017593,38.498252],[-1.018133,38.498167],[-1.018279,38.498147],[-1.01869,38.498383],[-1.019278,38.498794],[-1.01985,38.499065],