    SELECT 'matorrales-termomediterraneos-y-5330', '5330', 'Matorrales termomediterráneos y pre-estépicos', 'Matorral', 'El matorral de las zonas más cálidas y secas, allí donde prácticamente no hiela: palmito, espino negro, lentisco, cornicales, bojas, albaidas y esparto sobre laderas pedregosas y llanos soleados. Es un matorral abierto, con suelo desnudo a la vista entre mata y mata, y con muchas especies compartidas con el norte de África. Aguanta sequías de meses y rebrota en cuanto llueve.', 0, 38.482878, -1.04626, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.069729,38.479588],[-1.06967,38.479483],[-1.069569,38.479405],[-1.069437,38.479326],[-1.069321,38.479324],[-1.069189,38.479349],[-1.069043,38.479383],[-1.068913,38.479417],[-1.068767,38.479441],[-1.068636,38.479462],[-1.068519,38.479496],[-1.068402,38.479521],[-1.068286,38.479578],[-1.068169,38.47958],[-1.068052,38.479578],[-1.067907,38.47958],[-1.067746,38.479582],[-1.067615,38.479594],[-1.067484,38.479591],[-1.067338,38.479594],[-1.067192,38.479569],[-1.067075,38.479571],[-1.066959,38.479547],[-1.066783,38.479548],[-1.066609,38.479572],[-1.066492,38.479593],[-1.066346,38.479654],[-1.06623,38.479688],[-1.066099,38.479731],[-1.065997,38.479792],[-1.065895,38.479849],[-1.065778,38.47987],[-1.065647,38.479895],[-1.065502,38.47987],[-1.065326,38.47979],[-1.065224,38.479734],[-1.065092,38.479665],[-1.064961,38.479667],[-1.064816,38.479669],[-1.06467,38.479667],[-1.064553,38.479701],[-1.064407,38.479739],[-1.064262,38.479781],[-1.064102,38.479842],[-1.063985,38.47984],[-1.06381,38.479819],[-1.063678,38.479817],[-1.063533,38.479783],[-1.063401,38.479749],[-1.063241,38.479729],[-1.063066,38.479694],[-1.062949,38.479661],[-1.062818,38.479627],[-1.062657,38.479602],[-1.062541,38.479568],[-1.062424,38.479548],[-1.062293,38.479515],[-1.062147,38.47949],[-1.062016,38.479456],[-1.061899,38.479422],[-1.061753,38.479375],[-1.061607,38.479341],[-1.061505,38.479299],[-1.061388,38.479265],[-1.061272,38.479227],[-1