    SELECT 'Carraspique de Sierra Nevada', 'Iberis carnosa', 'flora', 'Hierba', NULL, 'Hierba vivaz, de tallo central corto, de cuya base parten tallos floríferos de 4-15 cm. Hojas alternas, simples, espatuladas. Flores zigomorfas, hermafroditas, en corimbos terminales; sépalos 4, libres, con margen membranáceo blanco o purpúreo; pétalos 4, libres, blancos o algo rosados, los dos externos más grandes; estambres 6, los dos laterales más cortos. Fruto silícula angustisepta, comprimido, con dos alas laterales.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Iberis_carnosa_2022-04-28_7901.jpg?width=1280', 'Salicyna (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Iberis', 'No evaluada en la Lista Roja mundial de la UICN', 'EN — En peligro (Lista Roja española, 2010)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 5335, 5377256, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Labiérnago', 'Phillyrea angustifolia', 'flora', 'Arbusto', 'Matorral mediterráneo y laderas secas sobre suelos pedregosos', 'Arbusto de hojas opuestas, estrechas y coriáceas, muy parecido a un acebuche pero con las hojas verdes por ambas caras. Sus frutos son pequeñas drupas azuladas o negras que consumen zorzales y currucas.', NULL, 'Hojas opuestas y estrechas, verdes por las dos caras; Sin el reverso plateado del acebuche; Frutos pequeños azulados o negros', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Phyllirea_angustifolia.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Phillyrea', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se