    SELECT 'Madroño', 'Arbutus unedo', 'flora', 'Arbusto', 'Umbrías, barrancos y matorral alto sobre suelos frescos', 'Arbusto o arbolillo de hojas lustrosas y dentadas y corteza rojiza que se desprende en tiras. En otoño coinciden en la misma rama las flores blancas en racimos colgantes y los frutos rojos y granulosos del año anterior.', NULL, 'Flores y frutos a la vez en la misma rama, en otoño; Frutos rojos esféricos de superficie granulosa; Corteza rojiza que se desprende en tiras finas', 'Otoño e invierno (flor y fruto a la vez)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arbutus_unedo_Corsica.jpg?width=1280', 'jxandreani (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Ericaceae', 'Arbutus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', NULL, 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo) · CEEEI: Incluido (Real Decreto 630/2013, de 2 de agosto) · y 1 figura más en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 2284, 2882803, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Campanillera', 'Campanula rapunculus', 'flora', NULL, 'Vive en herbazales, taludes y bosques, en cualquier tipo de sustrato', 'Planta bienal, con raíz algo leñosa, hasta de 1 m o más. Hojas espatuladas, atenuadas en el pecíolo, hasta de 10 x 2 cm, las de arriba más pequeñas y lanceoladas, levemente dentadas, glabras o con pelos. Flores dispuestas en racimos, pediceladas, con cáliz de 1-2 cm, acampanado, con cinco largos dientes. Corola de más de 2 cm, de color azul, glabra, con lóbulos agudos. Fruto hasta de 2 cm, que se abre por poros en la parte de arriba. Semillas minúsculas de menos de 1 mm.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Mayo a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Campanulaceae_-_Campanula_rapunculus-5.JPG?width=1280', 'Hectonichus (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Campanulaceae', 'Campanula', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 3010, 5411920, 2, NULL, NULL, NULL
    UNION ALL
