    SELECT 'Lentisco', 'Pistacia lentiscus', 'flora', 'Arbusto', 'Matorral mediterráneo litoral', 'Arbusto perennifolio de hojas compuestas sin foliolo terminal y con el raquis alado, un detalle que lo separa de la cornicabra. Al frotarlo huele intensamente a resina. Sus frutos, en racimo, pasan de rojo a negro y son alimento clave para aves en otoño.', NULL, 'Hoja compuesta con número par de foliolos, sin uno terminal; Raquis de la hoja con dos alas laterales; Olor fuerte a resina al frotar las hojas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus.jpg?width=1280', 'Lumbar~commonswiki (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', NULL, 'No catalogada (especie común mediterránea)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7129, 3190583, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10670, 2469763, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alcacionera', 'Pseudopodospermum hispanicum', 'flora', 'Hierba', 'Vive en tomillares y bordes de camino sobre cualquier sustrato, entre 200-1800 m', 'Hierba perenne, hasta de 70 cm, con hojas basales lanceoladas u ovadas, largamente acuminadas, enteras o laciniadas. Pedúnculos cilíndricos, con involucro hasta de 3,5 cm, con tres o cuatro filas de brácteas tomentosas, las externas aquilladas. Flores amarillas, con la base de color pardo y una franja púrpura en las flores externas, que sobresalen hasta 18 mm del involucro. Aquenios 12-22 mm.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a junio', NULL, NULL, NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Pseudopodospermum', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10428, 10854225, 2, NULL, NULL, NULL
    UNION ALL
