    SELECT 'Tablero de damas', 'Fritillaria lusitanica', 'flora', 'Planta bulbosa', 'Pastizales, claros de matorral y pedregales de montaña', 'Bulbosa de tallo fino y hojas estrechas que cuelga una o dos flores en forma de campana, con un jaspeado pardo y verdoso que recuerda a un tablero de ajedrez. Pasa desapercibida entre la hierba pese a su forma llamativa.', NULL, 'Flor colgante en campana con dibujo ajedrezado; Tallo fino con pocas hojas estrechas; Colores apagados que la camuflan en el pastizal', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fritillaria_lusitanica_2_2601.jpg?width=1280', 'Balles2601 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite, que la cita como «Fritillaria hispanica» (el backbone de GBIF lo trata como sinónimo de Fritillaria lusitanica), con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Liliales', 'Liliaceae', 'Fritillaria', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 4633, 5300414, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerrillo', 'Hyparrhenia hirta', 'flora', 'Gramínea', 'Laderas secas, ribazos y pastizales sobre suelos pedregosos', 'Gramínea perenne que forma matas y espiga en verano, cuando el resto del pastizal ya está agostado. Sus espiguillas van por parejas, cubiertas de pelos rojizos y con aristas retorcidas. Da al paisaje un tono dorado rojizo a final de verano.', NULL, 'Espiguillas peludas agrupadas por parejas; Aristas retorcidas y acodadas; Espiga en verano, cuando lo demás está seco', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hyparrhenia_hirta_Habitus_ValledeAlcudia.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Hyparrhenia', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10047, 2703243, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Chuntamanetas', 'Lonicera etrusca', 'flora', 'Arbusto', 'Vive en bosques mediterráneos esclerófilos y marcescentes y en sus orlas, hasta 1800 m', 'Arbusto trepador sarmentoso, con hojas de 3-6 x 2-3,5 cm, obovadas, opuestas y decusadas, caducas, algo coriáceas, sentadas, al menos el par superior soldadas en la base. Inflorescencia en glomérulos terminales pedunculados de entre seis y 12 flores de 3-4,5 cm, con largos tubos, de color blanco-amarillento o rojizo, con estilo exerto. Fruto en baya de 4,5-7 mm, ovoide,roja.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lonicera_etrusca.jpg?width=1280', 'en:User:Iorsh (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Dipsacales', 'Caprifoliaceae', 'Lonicera', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 6037, 5334247, 1, NULL, NULL, NULL
