    SELECT 'Martín pescador', 'Alcedo atthis', 'fauna', 'Ave acuática', 'Ríos, ramblas con pozas, canales y láminas de agua con posaderos y taludes terrosos', 'Pájaro rechoncho de color azul turquesa iridiscente por encima y naranja por debajo, con un pico largo y recto desproporcionado. Pesca lanzándose en picado desde una rama sobre el agua y anida en un túnel que excava en taludes de tierra.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', 'Destello azul eléctrico volando bajo y recto sobre el agua; Silbido agudo y penetrante, casi siempre antes de verlo; Posado inmóvil en una rama sobre el agua, cabeza gacha', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_Kingfisher_Alcedo_atthis.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 0 ocurrencias dentro del espacio (barrido de 2026-09-13); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000457 (Sierra de Salinas (ZEPA)), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Coraciiformes', 'Alcedinidae', 'Alcedo', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NT — Casi amenazada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 10794, 2475532, 0, 'ES0000457', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000457","name":"Sierra de Salinas (ZEPA)","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000457 (Sierra de Salinas (ZEPA)), sección 3.2"}'
    UNION ALL
    SELECT 'Águila perdicera', 'Aquila fasciata', 'fauna', 'Ave rapaz', 'Sierras con cortados rocosos y amplias zonas abiertas de matorral y cultivo para cazar', 'Águila mediana de alas largas y cola larga, con el vientre blanco finamente rayado y una mancha blanca en la espalda que se ve bien en vuelo. Caza a gran velocidad y a poca altura, sorprendiendo a perdices, conejos y palomas. Las parejas ocupan el mismo cortado durante años.', NULL, 'Mancha blanca en el centro de la espalda, visible desde arriba; Vientre claro y muy rayado, con una banda oscura en el borde del ala; Vuelo bajo y rápido cuando caza, no en círculos altos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_perdicera.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas: Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF confirma su presencia con 0 ocurrencias dentro del espacio (barrido de 2026-09-13); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000457 (Sierra de Salinas (ZEPA)), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Aquila', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'EN — En peligro (Lista Roja española, 2004)', 'Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021); Directiva Aves 2009/147/CE, Anexo I', 'En Peligro de Extinción (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 16302, 5844449, 0, 'ES0000457', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000457","name":"Sierra de Salinas (ZEPA)","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000457 (Sierra de Salinas (ZEPA)), sección 3.2"}'
