    SELECT 'culantrillo blanco menor', 'Asplenium fontanum', 'flora', 'Helecho', 'Vive en rocas calizas, entre 300-2200 m', 'Tiene un rizoma robusto, y frondes hasta de 25 cm, con pecíolo corto, verde, y lámina dos o tres veces pinnada, con hojillas alternas, las medianas mayores, y soros junto al nervio medio.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asplenium-fontanum-Soller.jpg?width=1280', 'Juan Bibiloni (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200008 (Sierra de Salinas), sección 3.3, que la cita como «Asplenium fontanum (L.) Bernh. subsp. fontanum»: escasa; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite, que la cita como «Asplenium fontanum subsp. fontanum», con la categoría «Vulnerable (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Aspleniaceae', 'Asplenium', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 2538, NULL, 0, NULL, NULL, NULL
    UNION ALL
    SELECT 'Camín real', 'Dictamnus hispanicus', 'flora', 'Hierba', 'Vive en lindes y orlas de encinar o pinar, o en formaciones de matorral, sobre sustratos básicos, hasta 1500 m', 'Planta herbácea perenne, hasta de 50 cm, con hojas de olor anisado, compuestas, de raquis ligeramente alado, con unos 15 folíolos ovados, denticulados. Inflorescencia racemiforme, hasta con 15 flores pediceladas, con sépalos de unos 5 mm y pétalos hasta de 2 cm, uncinados, lanceolados, de color crema a morado con líneas oscuras longitudinales. Fruto en cápsula formado por cinco folículos, con endocarpo que se dobla y lanza las semillas de unos 5 mm, ovoides, negras.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dictamnus_Hispanicus_(8755663794).jpg?width=1280', 'Juanedc from Zaragoza, España (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-09-13); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §1.1.2.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de la ZEC ES6200008 (1.337,8 ha), que solapa este Paisaje Protegido (2.395,4 ha) sin coincidir con su límite, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Rutaceae', 'Dictamnus', 'N